PRINT N'OP_917_tmp_NHM_Podaci: gotovo.';
SELECT Nivo, COUNT(*) AS Redova FROM planiranje.tmpNHM GROUP BY Nivo ORDER BY Nivo;
SELECT LEFT(Kod4, 2) AS Glava, COUNT(*) AS Redova FROM planiranje.tmpNHM GROUP BY LEFT(Kod4, 2) ORDER BY 1;
SELECT Kod8, Nivo, TarifniRazred, LEFT(NazivLat, 80) AS Naziv FROM planiranje.tmpNHM
